previewCss:
.darma-loader-darma-b16-semaphore-flags { --accent: var(--loader-color, #dc2626); --accent-2: var(--loader-secondary-color, #facc15); width: var(--loader-size, 118px); height: var(--loader-size, 118px); position: relative; }
.darma-loader-darma-b16-semaphore-flags .darma-loader-darma-b16-semaphore-flags__torso { position: absolute; left: 43%; top: 30%; width: 14%; height: 52%; border-radius: 8px 8px 5px 5px; background: linear-gradient(color-mix(in srgb, #fff 20%, var(--accent)), var(--accent)); }
.darma-loader-darma-b16-semaphore-flags .darma-loader-darma-b16-semaphore-flags__torso::before { content: ''; position: absolute; left: 2%; bottom: 100%; width: 96%; height: 34%; border-radius: 50%; background: var(--accent); }
.darma-loader-darma-b16-semaphore-flags .darma-loader-darma-b16-semaphore-flags__arm { position: absolute; left: 48%; top: 36%; width: 4%; height: 34%; border-radius: 3px; background: color-mix(in srgb, #0f172a 55%, transparent); transform-origin: 50% 0; }
.darma-loader-darma-b16-semaphore-flags .darma-loader-darma-b16-semaphore-flags__arm::after { content: ''; position: absolute; left: -180%; top: 76%; width: 460%; height: 40%; background: var(--accent-2); clip-path: polygon(0 0, 100% 20%, 100% 80%, 0 100%); }
.darma-loader-darma-b16-semaphore-flags .darma-loader-darma-b16-semaphore-flags__arm:nth-of-type(2) { animation: darma-loader-darma-b16-semaphore-flags-sema-left calc(var(--loader-speed, 1s) * 2.8) steps(1, end) infinite; }
.darma-loader-darma-b16-semaphore-flags .darma-loader-darma-b16-semaphore-flags__arm:nth-of-type(3) { animation: darma-loader-darma-b16-semaphore-flags-sema-right calc(var(--loader-speed, 1s) * 2.8) steps(1, end) infinite; }
@keyframes darma-loader-darma-b16-semaphore-flags-sema-left { 0%, 24% { transform: rotate(200deg); } 25%, 49% { transform: rotate(155deg); } 50%, 74% { transform: rotate(245deg); } 75%, 100% { transform: rotate(180deg); } }
@keyframes darma-loader-darma-b16-semaphore-flags-sema-right { 0%, 24% { transform: rotate(160deg); } 25%, 49% { transform: rotate(115deg); } 50%, 74% { transform: rotate(70deg); } 75%, 100% { transform: rotate(135deg); } }

